#!/usr/bin/env node
// bundle.js — build dist/mm2-engine.js: the engine + policies + partners + scenarios as one browser-ready IIFE exposing window.MM2.
// No bundler: the engine modules are plain ESM with no Node dependencies, so we strip import/export lines and concatenate.
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { loadPolicies, loadPartners, loadScenarios } from '../src/engine/load.js';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const order = ['money', 'policy', 'evidence', 'router', 'ledger', 'settlement', 'trace', 'perimeter', 'controlplane', 'scenario'];
let out = '/* mm2-engine.js — generated by scripts/bundle.js from src/engine/*.js. Do not edit. */\n(function(global){\n"use strict";\n';
for (const name of order) {
  let src = readFileSync(join(root, 'src', 'engine', `${name}.js`), 'utf8');
  src = src.replace(/^import[^\n]*\n/gm, '').replace(/^export\s+\{[^}]*\}[^\n]*\n/gm, '').replace(/^export\s+/gm, '');
  out += `\n// ---- ${name}.js ----\n${src}\n`;
}
out += `\nconst POLICIES = ${JSON.stringify(loadPolicies())};\nconst PARTNERS = ${JSON.stringify(loadPartners())};\nconst SCENARIOS = ${JSON.stringify(loadScenarios())};\n`;
out += `global.MM2 = { ControlPlane, validatePolicy, evaluateEvidence, gate, registerProvider, route, Ledger, selectRail, priceRoute, NettingWindow, RAILS, renderTrace, summarizeTrail, derivePerimeter, buildIntent, deepMerge, money, convert, fmt, FX, POLICIES, PARTNERS, SCENARIOS, version: '0.1.0' };\n})(typeof window !== 'undefined' ? window : globalThis);\n`;
mkdirSync(join(root, 'dist'), { recursive: true });
writeFileSync(join(root, 'dist', 'mm2-engine.js'), out);
console.log(`dist/mm2-engine.js — ${(out.length / 1024).toFixed(1)} KB`);
